import * as React from 'react'
import type {EntryPointProps} from 'react-relay'

import type {Branch} from '../../../services/rest'

import type {BranchSelectBranchesQuery} from './__generated__/BranchSelectBranchesQuery.graphql'
import BranchSelectContainer from './BranchSelect.container'
import type {BranchSelectBaseProps, OwnProps} from './BranchSelect.types'

type Queries = {branches: BranchSelectBranchesQuery}

export default function BranchSelectStandalone({
  queries,
  props,
}: EntryPointProps<Queries, {}, OwnProps<BranchSelectBaseProps>, {}>): React.ReactElement | null {
  const {selected: initialSelected, onSelect, ...restProps} = props
  const [selected, setSelected] = React.useState(initialSelected)
  const handleSelect = React.useCallback(
    (nextSelected: Branch | null | undefined, replace?: boolean) => {
      setSelected(nextSelected)
      onSelect(nextSelected, replace)
    },
    [onSelect],
  )
  return (
    <BranchSelectContainer
      {...restProps}
      selected={selected}
      onSelect={handleSelect}
      branchesQueryRef={queries.branches}
    />
  )
}
export type BranchSelectStandaloneComponent = typeof BranchSelectStandalone
